import java.util.*;
import java.io.*;

public class Main {
    static long[][] highFive(long[][] entries) {
        // Write your solution here
        // Return {id, average} rows sorted by id
        return new long[0][];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[][] entries = new long[n][2];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            entries[i][0] = (long) in.nval;
            in.nextToken();
            entries[i][1] = (long) in.nval;
        }
        StringBuilder sb = new StringBuilder();
        for (long[] row : highFive(entries)) sb.append(row[0]).append(" ").append(row[1]).append("\n");
        System.out.print(sb);
    }
}
